python3 - <<'PY'
import sqlite3, json
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
rows = con.execute("SELECT slug, local_ref_id, connections_produced FROM citation_mining ORDER BY slug, local_ref_id").fetchall()
print("total rows:", len(rows))
shapes = {}
for slug, lref, v in rows:
    try:
        parsed = json.loads(v)
        shape = type(parsed).__name__
    except Exception as e:
        shape = f"UNPARSEABLE:{e}"
    shapes.setdefault(shape, []).append((slug, lref, v[:40] if isinstance(v,str) else v))
for shape, items in shapes.items():
    print(f"--- {shape}: {len(items)} ---")
    for it in items[:5]:
        print("   ", it)
PY

